UPDATE ui.masterconfig SET
configjson = '[{"sql":"select iaccountid, array_agg(distinct ipayeemccid)\nfrom purview group by iaccountid","tooltip":"Distinct MCCs transacting with Account","description":"Distinct MCCs transacting with Account"},{"sql":"SELECT iaccountid, sum(dobservationamount)\nFROM purview WHERE bside = false GROUP BY iaccountid","tooltip":"Total Value as payer","description":"Total Value as payer"},{"sql":"SELECT iaccountid, count(ilivemessageid)\nFROM purview WHERE bside = true GROUP BY iaccountid","tooltip":"Total count as payee","description":"Total count as payee"},{"sql":"SELECT iaccountid, map_from_entries(array_agg(struct(`txn.class`, `count(ilivemessageid)`)))\nas byclass\nFROM (SELECT iaccountid, `txn.class`, count(ilivemessageid)\nFROM purview GROUP BY iaccountid, `txn.class`)\nGROUP BY iaccountid","tooltip":"Total Value by Class","description":"Total Value by Class"},{"sql":"select iaccountid, map_from_entries(collect_list(struct(ovpaid, count))) as relationshipCount\nfrom ( select iaccountid, ovpaid, count(ilivemessageid) as count\nfrom purview where `txn.type` = ''PAY'' and bside = true group by iaccountid, ovpaid )\nas a group by iaccountid","tooltip":"Payer wise total Count with an Account as Payee","description":"Payer wise total Count with an Account as Payee"},{"sql":"select iaccountid, map_from_entries(collect_list(struct(ovpaid, value))) as relationshipValue\nfrom ( select iaccountid, ovpaid, sum(dobservationamount) as value\nfrom purview where `txn.type` = ''PAY'' and bside = true group by iaccountid, ovpaid )\nas a group by iaccountid","tooltip":"Payee wise total Value  with an Account","description":"Payee wise total Value  with an Account"},{"sql":"select iaccountid,count(distinct ovpaid)\nfrom purview where dobservationamount > 5000 and `txn.attribs.p2p_p2m`=''P2P'' and bside=true\ngroup by iaccountid","tooltip":"Distinct count of payers transacting with Account","description":"Distinct count of payers transacting with Account"},{"sql":"\nWITH history AS (\n    SELECT iaccountid, SUM(dobservationamount) AS volume\n    FROM purview\n    WHERE tdate < to_date(''{adjusted_tdate}'') and bside=true\n    GROUP BY iaccountid\n),\nrecent AS (\n    SELECT iaccountid, SUM(dobservationamount) AS volume\n    FROM purview\n    WHERE tdate >= to_date(''{adjusted_tdate}'') - interval ''1'' month and bside=true\n    GROUP BY iaccountid\n)\nSELECT recent.iaccountid, history.volume/3 AS avg_history\nFROM recent LEFT JOIN history on recent.iaccountid = history.iaccountid","tooltip":"Avg Monthly Value Of Payer","description":"Avg Monthly Value Of Payer"},{"sql":"WITH sim AS ( SELECT iaccountid, dobservationamount, SUM(dobservationamount)\nAS volume FROM purview GROUP BY iaccountid, dobservationamount\nHAVING COUNT(1) > 1 ),\nsim_totals AS\n( SELECT iaccountid, SUM(volume) as volume\nFROM sim GROUP BY iaccountid HAVING SUM(volume) > 100000 ),\ntotals AS ( SELECT p.iaccountid, sum(p.dobservationamount) AS volume\nFROM purview p GROUP BY p.iaccountid )\nSELECT st.iaccountid, st.volume AS sim_volume, t.volume,\n(st.volume/t.volume)*100 AS per, st.volume > t.volume * 0.3 AS gt30per\nFROM sim_totals st LEFT JOIN totals t ON st.iaccountid = t.iaccountid","tooltip":"Identical payment transactions for an account","description":"Identical payment transactions for an account"},{"sql":"SELECT iaccountid, sum(dobservationamount) FROM\npurview WHERE bside = true\n`observations.payerVPA.account.customer.attribs.isOnbLocRisky` = ''true''\nAND GROUP BY iaccountid\n","tooltip":"Aggr Value for payer account with risky onboardings","description":"Aggr Value for payer account with risky onboardings"},{"sql":"select iaccountid, map_from_entries(collect_list(struct(country, count))) as \ncountryWiseCount from (\nselect iaccountid, get_json_object(`observations.geolocation`, ''$.country'') as country, count(1) as count\nfrom purview\nwhere bside = false\nand get_json_object(`observations.geolocation`, ''$.country'') != ''-1''\ngroup by iaccountid, get_json_object(`observations.geolocation`, ''$.country'')\norder by iaccountid, country\n)\ngroup by iaccountid","tooltip":"Country wise split of txns for account as payer","description":"Country wise split of txns for account as payer"}]'::jsonb WHERE
iconfigid = 4;